/**
 * OpenAPI 3.0.3 specification for the PortionBridge API.
 *
 * This file is a plain, hand-written JS object — not generated by scanning
 * JSDoc comments in route files (no swagger-jsdoc dependency, no comments
 * added to any route/controller file). It was built by reading the actual
 * routes, controllers, services, and validators, so it reflects the real
 * implementation rather than an aspirational contract.
 *
 * Served by swagger-ui-express — see app.js (mounted only when
 * NODE_ENV !== 'production', matching this project's existing
 * environment-gated pattern for e.g. morgan('dev')).
 *
 * IMPORTANT: if the actual routes/controllers/validators change, this file
 * must be updated to match — it is not auto-synced with the code.
 */

const HTTP_STATUS = require('../constants').HTTP_STATUS;

const DONATION_STATUS_VALUES = ['pending', 'accepted', 'scheduled', 'on_the_way', 'picked_up', 'completed'];
const DONATION_CATEGORY_VALUES = ['food', 'clothes'];
const USER_ROLE_VALUES = ['donor', 'volunteer', 'admin'];
const NOTIFICATION_TYPE_VALUES = [
  'donation_accepted',
  'new_message',
  'status_updated',
  'rating_received',
  'report_filed',
];
const REPORT_STATUS_VALUES = ['pending', 'reviewed', 'resolved'];

// --- Reusable response envelopes -------------------------------------------

const successEnvelope = (dataSchema, description = 'Success') => ({
  description,
  content: {
    'application/json': {
      schema: {
        type: 'object',
        properties: {
          success: { type: 'boolean', example: true },
          message: { type: 'string' },
          data: dataSchema,
        },
      },
    },
  },
});

const paginatedEnvelope = (itemsPropertyName, itemSchema, description = 'Success') => ({
  description,
  content: {
    'application/json': {
      schema: {
        type: 'object',
        properties: {
          success: { type: 'boolean', example: true },
          message: { type: 'string' },
          data: {
            type: 'object',
            properties: {
              [itemsPropertyName]: { type: 'array', items: itemSchema },
            },
          },
          meta: { $ref: '#/components/schemas/PaginationMeta' },
        },
      },
    },
  },
});

const errorResponse = (description, example) => ({
  description,
  content: {
    'application/json': {
      schema: { $ref: '#/components/schemas/ErrorResponse' },
      example,
    },
  },
});

const commonErrors = {
  401: errorResponse('Not authenticated — missing/invalid/expired access token.', {
    success: false,
    message: 'Authentication required. No token provided.',
  }),
  403: errorResponse('Authenticated, but not authorized for this resource/action.', {
    success: false,
    message: 'Access denied. Required role(s): admin.',
  }),
  404: errorResponse('Resource not found.', {
    success: false,
    message: 'Donation request not found.',
  }),
  409: errorResponse('Conflict with the current state of the resource (e.g. wrong status, already exists).', {
    success: false,
    message: 'This donation request can no longer be modified because its status is "accepted".',
  }),
  422: errorResponse('Validation failed for one or more fields.', {
    success: false,
    message: 'Validation failed',
    errors: [{ field: 'email', message: 'A valid email address is required.' }],
  }),
  429: errorResponse('Rate limit exceeded.', {
    success: false,
    message: 'Too many requests. Please try again later.',
  }),
};

const pageParam = {
  name: 'page', in: 'query', required: false,
  schema: { type: 'integer', minimum: 1, default: 1 },
  description: 'Page number (1-indexed). Invalid values silently fall back to the default.',
};
const limitParam = {
  name: 'limit', in: 'query', required: false,
  schema: { type: 'integer', minimum: 1, maximum: 100, default: 10 },
  description: 'Results per page, capped at 100. Invalid values silently fall back to the default.',
};
const sortOrderParam = {
  name: 'sortOrder', in: 'query', required: false,
  schema: { type: 'string', enum: ['asc', 'desc'] },
};
const idPathParam = (name, description) => ({
  name, in: 'path', required: true, schema: { type: 'integer', minimum: 1 }, description,
});
const bearerSecurity = [{ bearerAuth: [] }];

// --- Schemas ----------------------------------------------------------------

const schemas = {
  ErrorResponse: {
    type: 'object',
    properties: {
      success: { type: 'boolean', example: false },
      message: { type: 'string' },
      errors: {
        type: 'array',
        nullable: true,
        description: 'Present only for 422 validation failures.',
        items: {
          type: 'object',
          properties: { field: { type: 'string' }, message: { type: 'string' } },
        },
      },
    },
  },

  PaginationMeta: {
    type: 'object',
    properties: {
      page: { type: 'integer' },
      limit: { type: 'integer' },
      totalItems: { type: 'integer' },
      totalPages: { type: 'integer' },
    },
  },

  User: {
    type: 'object',
    description:
      'Sanitized user object — never includes password hash, failed_login_attempts, lock_until, ' +
      'last_login_ip, last_user_agent, or is_deleted (see utils/helpers.js#sanitizeUser).',
    properties: {
      id: { type: 'integer' },
      name: { type: 'string' },
      email: { type: 'string', format: 'email' },
      role: { type: 'string', enum: USER_ROLE_VALUES },
      phone: { type: 'string', nullable: true },
      address: { type: 'string', nullable: true },
      profile_photo: { type: 'string', nullable: true, description: 'Relative path under /uploads/profiles/.' },
      email_verified: { type: 'boolean' },
      is_banned: { type: 'boolean' },
      last_login_at: { type: 'string', format: 'date-time', nullable: true },
      created_at: { type: 'string', format: 'date-time' },
      updated_at: { type: 'string', format: 'date-time' },
    },
  },

  Donation: {
    type: 'object',
    properties: {
      id: { type: 'integer' },
      donor_id: { type: 'integer' },
      volunteer_id: { type: 'integer', nullable: true },
      category: { type: 'string', enum: DONATION_CATEGORY_VALUES },
      quantity: { type: 'integer' },
      description: { type: 'string', nullable: true },
      photo: { type: 'string', nullable: true, description: 'Relative path under /uploads/donations/.' },
      pickup_location: { type: 'string' },
      pickup_time: { type: 'string', format: 'date-time' },
      scheduled_at: { type: 'string', format: 'date-time', nullable: true },
      accepted_at: { type: 'string', format: 'date-time', nullable: true },
      completed_at: { type: 'string', format: 'date-time', nullable: true },
      status: { type: 'string', enum: DONATION_STATUS_VALUES },
      created_at: { type: 'string', format: 'date-time' },
      updated_at: { type: 'string', format: 'date-time' },
    },
  },

  DonationParticipant: {
    type: 'object',
    nullable: true,
    description: 'null for volunteer until the donation is accepted.',
    properties: {
      id: { type: 'integer' },
      name: { type: 'string' },
      role: { type: 'string', enum: USER_ROLE_VALUES },
      profile_photo: { type: 'string', nullable: true },
    },
  },

  DonationDetail: {
    allOf: [
      { $ref: '#/components/schemas/Donation' },
      {
        type: 'object',
        properties: {
          donor: { $ref: '#/components/schemas/DonationParticipant' },
          volunteer: { $ref: '#/components/schemas/DonationParticipant' },
        },
      },
    ],
  },

  DonationStatusHistoryEntry: {
    type: 'object',
    properties: {
      id: { type: 'integer' },
      donation_request_id: { type: 'integer' },
      old_status: { type: 'string', nullable: true, enum: DONATION_STATUS_VALUES },
      new_status: { type: 'string', enum: DONATION_STATUS_VALUES },
      changed_at: { type: 'string', format: 'date-time' },
      changed_by: { type: 'integer', nullable: true },
      changed_by_name: { type: 'string', nullable: true },
      changed_by_role: { type: 'string', nullable: true, enum: USER_ROLE_VALUES },
    },
  },

  DonationHistorySummary: {
    type: 'object',
    description: 'Status counts. Exact keys differ for donor vs volunteer — see description on each endpoint.',
    properties: {
      total: { type: 'integer' },
      pending: { type: 'integer', description: 'Donor summary only.' },
      accepted: { type: 'integer' },
      scheduled: { type: 'integer' },
      completed: { type: 'integer' },
    },
  },

  Rating: {
    type: 'object',
    properties: {
      id: { type: 'integer' },
      donation_request_id: { type: 'integer' },
      rated_by: { type: 'integer', description: 'User who submitted the rating.' },
      rated_user: { type: 'integer', description: 'User being rated.' },
      stars: { type: 'integer', minimum: 1, maximum: 5 },
      comment: { type: 'string', nullable: true },
      created_at: { type: 'string', format: 'date-time' },
    },
  },

  LeaderboardDonorEntry: {
    type: 'object',
    properties: {
      user_id: { type: 'integer' },
      donor_name: { type: 'string' },
      profile_photo: { type: 'string', nullable: true },
      total_donations: { type: 'integer' },
      completed_count: { type: 'integer' },
      total_quantity_donated: { type: 'integer' },
      average_rating: { type: 'number', nullable: true, format: 'float' },
    },
  },

  LeaderboardVolunteerEntry: {
    type: 'object',
    properties: {
      user_id: { type: 'integer' },
      volunteer_name: { type: 'string' },
      profile_photo: { type: 'string', nullable: true },
      total_pickups: { type: 'integer' },
      completed_count: { type: 'integer' },
      average_rating: { type: 'number', nullable: true, format: 'float' },
    },
  },

  Notification: {
    type: 'object',
    properties: {
      id: { type: 'integer' },
      user_id: { type: 'integer' },
      type: { type: 'string', enum: NOTIFICATION_TYPE_VALUES },
      title: { type: 'string' },
      message: { type: 'string' },
      related_id: { type: 'integer', nullable: true },
      is_read: { type: 'boolean' },
      created_at: { type: 'string', format: 'date-time' },
    },
  },

  ChatMessage: {
    type: 'object',
    properties: {
      id: { type: 'integer' },
      donation_request_id: { type: 'integer' },
      sender_id: { type: 'integer' },
      sender_name: { type: 'string' },
      sender_role: { type: 'string', enum: USER_ROLE_VALUES },
      message: { type: 'string' },
      is_read: { type: 'boolean' },
      created_at: { type: 'string', format: 'date-time' },
    },
  },

  Report: {
    type: 'object',
    properties: {
      id: { type: 'integer' },
      reporter_id: { type: 'integer' },
      reported_user_id: { type: 'integer', nullable: true },
      reported_donation_id: { type: 'integer', nullable: true },
      reason: { type: 'string' },
      details: { type: 'string', nullable: true },
      status: { type: 'string', enum: REPORT_STATUS_VALUES },
      created_at: { type: 'string', format: 'date-time' },
    },
  },
};

module.exports = {
  openapi: '3.0.3',
  info: {
    title: 'PortionBridge API',
    version: '1.0.0',
    description:
      'Food & clothes donation coordination platform. All responses use the standard envelope ' +
      '{ success, message, data, meta? } (see utils/apiResponse.js). Validation failures return ' +
      '422 with an `errors` array of { field, message }. This document only describes endpoints ' +
      'that exist in the current implementation — see the "Known gaps" section in the project docs ' +
      'for anything intentionally left undocumented because it does not exist yet.\n\n' +
      'Real-time features (chat messages, notifications, live donation status) are delivered over ' +
      'Socket.IO, not REST polling — see docs/socketEvents.md for the full event reference.',
  },
  servers: [
    { url: '/api/v1', description: 'Current server (relative — works in any environment)' },
  ],
  tags: [
    { name: 'Auth', description: 'Registration, login, session/token management, own-profile management.' },
    { name: 'Donations', description: 'Donation CRUD, lifecycle, detail view, donor history/dashboard.' },
    { name: 'Volunteer', description: 'Volunteer dashboard and assignment views.' },
    { name: 'Uploads', description: 'Donation image and profile photo uploads.' },
    { name: 'Ratings', description: 'Mutual donor <-> volunteer ratings after a completed donation.' },
    { name: 'Leaderboard', description: 'Read-only aggregate donor/volunteer rankings.' },
    { name: 'Reports', description: 'User-filed reports about a donation/participant.' },
    { name: 'Chat', description: 'REST reads for donation-scoped chat history (sending is Socket.IO-only).' },
    { name: 'Notifications', description: 'In-app notification list/read-state.' },
    { name: 'Admin', description: 'Admin-only oversight: users, donations, volunteers.' },
    { name: 'Health', description: 'Service liveness check.' },
  ],
  components: {
    securitySchemes: {
      bearerAuth: {
        type: 'http',
        scheme: 'bearer',
        bearerFormat: 'JWT',
        description:
          'Short-lived access token from /auth/login or /auth/refresh-token, sent as ' +
          '"Authorization: Bearer <token>". A subset of Auth endpoints additionally rely on an ' +
          'httpOnly refresh-token cookie (never sent via this header) plus a CSRF header — see ' +
          'each endpoint\'s description.',
      },
    },
    schemas,
  },
  paths: buildPaths(),
};

// ---------------------------------------------------------------------------
// Paths are built in a function (rather than a giant inline literal) purely
// for readability — the returned object is the same static structure either way.
// ---------------------------------------------------------------------------
function buildPaths() {
  const paths = {};

  Object.assign(paths, authPaths());
  Object.assign(paths, donationPaths());
  Object.assign(paths, volunteerPaths());
  Object.assign(paths, uploadPaths());
  Object.assign(paths, ratingPaths());
  Object.assign(paths, leaderboardPaths());
  Object.assign(paths, reportPaths());
  Object.assign(paths, chatPaths());
  Object.assign(paths, notificationPaths());
  Object.assign(paths, adminPaths());
  Object.assign(paths, healthPaths());

  return paths;
}

// --- Auth --------------------------------------------------------------

function authPaths() {
  return {
    '/auth/register': {
      post: {
        tags: ['Auth'],
        summary: 'Register a new account',
        description:
          'Public. Rate-limited (5 per hour per IP — registerLimiter). Role defaults to "donor" if ' +
          'omitted; only "donor"/"volunteer" may self-register ("admin" cannot). Sends a verification ' +
          'email; the account cannot log in until verified.',
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: {
                type: 'object',
                required: ['name', 'email', 'password'],
                properties: {
                  name: { type: 'string', minLength: 2, maxLength: 100 },
                  email: { type: 'string', format: 'email' },
                  password: {
                    type: 'string',
                    description: '8-64 chars, needs upper+lower+number+special char, rejects common weak passwords.',
                  },
                  role: { type: 'string', enum: ['donor', 'volunteer'], default: 'donor' },
                  phone: { type: 'string', minLength: 7, maxLength: 20, nullable: true },
                  address: { type: 'string', maxLength: 255, nullable: true },
                },
              },
              example: { name: 'Asha Rahman', email: 'asha@example.com', password: 'Str0ng!Passw0rd', role: 'donor' },
            },
          },
        },
        responses: {
          201: successEnvelope({ type: 'object', properties: { user: { $ref: '#/components/schemas/User' } } }, 'Account created.'),
          409: commonErrors[409],
          422: commonErrors[422],
          429: commonErrors[429],
        },
      },
    },
    '/auth/verify-email': {
      post: {
        tags: ['Auth'],
        summary: 'Verify an email address',
        description: 'Public. Consumes the single-use token emailed at registration/resend.',
        requestBody: {
          required: true,
          content: { 'application/json': { schema: { type: 'object', required: ['token'], properties: { token: { type: 'string' } } } } },
        },
        responses: { 200: successEnvelope(null, 'Email verified.'), 400: commonErrors[409], 422: commonErrors[422] },
      },
    },
    '/auth/resend-verification': {
      post: {
        tags: ['Auth'],
        summary: 'Resend the verification email',
        description: 'Public. Always returns 200 regardless of whether the email exists (avoids account enumeration).',
        requestBody: {
          required: true,
          content: { 'application/json': { schema: { type: 'object', required: ['email'], properties: { email: { type: 'string', format: 'email' } } } } },
        },
        responses: { 200: successEnvelope(null, 'If that account exists, a verification email has been sent.'), 422: commonErrors[422] },
      },
    },
    '/auth/login': {
      post: {
        tags: ['Auth'],
        summary: 'Log in',
        description:
          'Public. Rate-limited (10 failed attempts per 15 min per IP — loginLimiter; successful ' +
          'logins do not count against it). Also enforces a per-account lockout after repeated failures ' +
          '(see AUTH.ACCOUNT_LOCK_MAX_ATTEMPTS). On success, sets an httpOnly refresh-token cookie and a ' +
          'readable CSRF cookie in addition to returning the access token in the body.',
        requestBody: {
          required: true,
          content: { 'application/json': { schema: { type: 'object', required: ['email', 'password'], properties: { email: { type: 'string', format: 'email' }, password: { type: 'string' } } } } },
        },
        responses: {
          200: successEnvelope({ type: 'object', properties: { user: { $ref: '#/components/schemas/User' }, accessToken: { type: 'string' } } }, 'Logged in.'),
          401: commonErrors[401],
          403: errorResponse('Account banned or locked out.', { success: false, message: 'Your account has been banned. Contact support for assistance.' }),
          422: commonErrors[422],
          429: commonErrors[429],
        },
      },
    },
    '/auth/refresh-token': {
      post: {
        tags: ['Auth'],
        summary: 'Exchange the refresh-token cookie for a new access token',
        description:
          'Requires the httpOnly refresh-token cookie (set by login/register/refresh) AND a matching ' +
          '"x-csrf-token" header equal to the readable csrfToken cookie (double-submit CSRF pattern). ' +
          'Rotates the refresh token; the old one is invalidated (reuse of an already-rotated token is ' +
          'treated as a possible theft and revokes the whole session family).',
        responses: {
          200: successEnvelope({ type: 'object', properties: { user: { $ref: '#/components/schemas/User' }, accessToken: { type: 'string' } } }, 'Token refreshed.'),
          401: errorResponse('No/invalid/expired refresh token.', { success: false, message: 'No refresh token provided. Please log in again.' }),
          403: errorResponse('CSRF token missing or mismatched.', { success: false, message: 'CSRF token missing. Request rejected.' }),
        },
      },
    },
    '/auth/logout': {
      post: {
        tags: ['Auth'],
        summary: 'Log out the current session/device',
        description: 'Requires the refresh-token cookie + CSRF header (same pattern as /refresh-token). Clears both cookies.',
        responses: { 200: successEnvelope(null, 'Logged out.'), 403: commonErrors[403] },
      },
    },
    '/auth/logout-all': {
      post: {
        tags: ['Auth'],
        summary: 'Log out every device/session',
        description: 'Requires a valid access token AND the refresh-token cookie + CSRF header.',
        security: bearerSecurity,
        responses: { 200: successEnvelope(null, 'Logged out everywhere.'), 401: commonErrors[401], 403: commonErrors[403] },
      },
    },
    '/auth/forgot-password': {
      post: {
        tags: ['Auth'],
        summary: 'Request a password reset email',
        description: 'Public. Always returns 200 regardless of whether the email exists.',
        requestBody: {
          required: true,
          content: { 'application/json': { schema: { type: 'object', required: ['email'], properties: { email: { type: 'string', format: 'email' } } } } },
        },
        responses: { 200: successEnvelope(null, 'If that account exists, a reset email has been sent.'), 422: commonErrors[422] },
      },
    },
    '/auth/reset-password': {
      post: {
        tags: ['Auth'],
        summary: 'Reset password using an emailed token',
        description: 'Public. Consumes a single-use reset token. Revokes every active session on success.',
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { type: 'object', required: ['token', 'newPassword'], properties: { token: { type: 'string' }, newPassword: { type: 'string' } } },
            },
          },
        },
        responses: { 200: successEnvelope(null, 'Password reset.'), 400: commonErrors[409], 422: commonErrors[422] },
      },
    },
    '/auth/me': {
      get: {
        tags: ['Auth'],
        summary: "Get the authenticated user's own profile",
        security: bearerSecurity,
        responses: { 200: successEnvelope({ type: 'object', properties: { user: { $ref: '#/components/schemas/User' } } }), 401: commonErrors[401] },
      },
      patch: {
        tags: ['Auth'],
        summary: "Update the authenticated user's own profile",
        description:
          'Only name/phone/address are editable here. role, email, password, and emailVerified are ' +
          'explicitly rejected (422) if present in the body — they can only change via their own dedicated flows.',
        security: bearerSecurity,
        requestBody: {
          content: {
            'application/json': {
              schema: {
                type: 'object',
                properties: {
                  name: { type: 'string', minLength: 2, maxLength: 100 },
                  phone: { type: 'string', minLength: 7, maxLength: 20 },
                  address: { type: 'string', maxLength: 255 },
                },
              },
            },
          },
        },
        responses: {
          200: successEnvelope({ type: 'object', properties: { user: { $ref: '#/components/schemas/User' } } }, 'Profile updated.'),
          401: commonErrors[401],
          422: commonErrors[422],
        },
      },
    },
    '/auth/change-password': {
      post: {
        tags: ['Auth'],
        summary: "Change the authenticated user's password",
        description:
          'Verifies currentPassword, rejects reuse of the last 5 passwords (AUTH.PASSWORD_HISTORY_LIMIT), ' +
          'and revokes every active session (including this one) on success — the client should treat a ' +
          '200 here as "logged out, please log in again."',
        security: bearerSecurity,
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: { type: 'object', required: ['currentPassword', 'newPassword'], properties: { currentPassword: { type: 'string' }, newPassword: { type: 'string' } } },
            },
          },
        },
        responses: {
          200: successEnvelope(null, 'Password changed — please log in again.'),
          401: errorResponse('Current password incorrect.', { success: false, message: 'Current password is incorrect.' }),
          422: commonErrors[422],
        },
      },
    },
    '/auth/admin-check': {
      get: {
        tags: ['Auth'],
        summary: 'Role-authorization smoke test (admin only)',
        security: bearerSecurity,
        responses: { 200: successEnvelope(null), 401: commonErrors[401], 403: commonErrors[403] },
      },
    },
  };
}

// --- Donations -----------------------------------------------------------

function donationPaths() {
  return {
    '/donations': {
      get: {
        tags: ['Donations'],
        summary: 'Browse pending donation requests',
        description: 'Volunteer or admin only. Only ever returns status=pending requests.',
        security: bearerSecurity,
        parameters: [
          { name: 'category', in: 'query', schema: { type: 'string', enum: DONATION_CATEGORY_VALUES } },
          { name: 'location', in: 'query', schema: { type: 'string', maxLength: 255 } },
          { name: 'search', in: 'query', schema: { type: 'string', maxLength: 255 } },
          { name: 'sortBy', in: 'query', schema: { type: 'string', enum: ['created_at', 'pickup_time', 'quantity'] } },
          sortOrderParam, pageParam, limitParam,
        ],
        responses: { 200: paginatedEnvelope('donations', { $ref: '#/components/schemas/Donation' }), 401: commonErrors[401], 403: commonErrors[403], 422: commonErrors[422] },
      },
      post: {
        tags: ['Donations'],
        summary: 'Create a donation request',
        description: 'Donor only.',
        security: bearerSecurity,
        requestBody: {
          required: true,
          content: {
            'application/json': {
              schema: {
                type: 'object',
                required: ['category', 'quantity', 'pickupLocation', 'pickupTime'],
                properties: {
                  category: { type: 'string', enum: DONATION_CATEGORY_VALUES },
                  quantity: { type: 'integer', minimum: 1 },
                  description: { type: 'string', maxLength: 500, nullable: true },
                  photo: { type: 'string', maxLength: 255, nullable: true, description: 'Set via POST /uploads/donation/{id}/image after creation, not directly here.' },
                  pickupLocation: { type: 'string', maxLength: 255 },
                  pickupTime: { type: 'string', format: 'date-time', description: 'Must be in the future.' },
                },
              },
            },
          },
        },
        responses: { 201: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 422: commonErrors[422] },
      },
    },
    '/donations/my-history/summary': {
      get: {
        tags: ['Donations'],
        summary: "Status-count summary of the donor's own donations",
        description: 'Donor only. Counts: total, pending, accepted, scheduled, completed. Does NOT include on_the_way/picked_up (known gap — see project notes) or cancelled (soft-deleted, not counted anywhere).',
        security: bearerSecurity,
        responses: { 200: successEnvelope({ type: 'object', properties: { summary: { $ref: '#/components/schemas/DonationHistorySummary' } } }), 401: commonErrors[401], 403: commonErrors[403] },
      },
    },
    '/donations/my-history': {
      get: {
        tags: ['Donations'],
        summary: "Full donation history for the authenticated donor",
        description: 'Donor only. Any status (not just pending), filterable.',
        security: bearerSecurity,
        parameters: [
          { name: 'status', in: 'query', schema: { type: 'string', enum: DONATION_STATUS_VALUES } },
          { name: 'category', in: 'query', schema: { type: 'string', enum: DONATION_CATEGORY_VALUES } },
          { name: 'search', in: 'query', schema: { type: 'string', maxLength: 255 } },
          { name: 'sortBy', in: 'query', schema: { type: 'string', enum: ['created_at', 'pickup_time', 'scheduled_at', 'completed_at'] } },
          sortOrderParam, pageParam, limitParam,
        ],
        responses: { 200: paginatedEnvelope('donations', { $ref: '#/components/schemas/Donation' }), 401: commonErrors[401], 403: commonErrors[403], 422: commonErrors[422] },
      },
    },
    '/donations/assigned-history/summary': {
      get: {
        tags: ['Donations'],
        summary: 'Status-count summary of donations assigned to the authenticated volunteer',
        description: 'Volunteer only. Counts: total, accepted, scheduled, completed (no pending bucket — a volunteer is never assigned a pending donation).',
        security: bearerSecurity,
        responses: { 200: successEnvelope({ type: 'object', properties: { summary: { $ref: '#/components/schemas/DonationHistorySummary' } } }), 401: commonErrors[401], 403: commonErrors[403] },
      },
    },
    '/donations/assigned-history': {
      get: {
        tags: ['Donations'],
        summary: 'Full history of donations assigned to the authenticated volunteer',
        description: 'Volunteer only. Same filter/sort/pagination contract as /my-history.',
        security: bearerSecurity,
        parameters: [
          { name: 'status', in: 'query', schema: { type: 'string', enum: DONATION_STATUS_VALUES } },
          { name: 'category', in: 'query', schema: { type: 'string', enum: DONATION_CATEGORY_VALUES } },
          { name: 'search', in: 'query', schema: { type: 'string', maxLength: 255 } },
          { name: 'sortBy', in: 'query', schema: { type: 'string', enum: ['created_at', 'pickup_time', 'scheduled_at', 'completed_at'] } },
          sortOrderParam, pageParam, limitParam,
        ],
        responses: { 200: paginatedEnvelope('donations', { $ref: '#/components/schemas/Donation' }), 401: commonErrors[401], 403: commonErrors[403], 422: commonErrors[422] },
      },
    },
    '/donations/{id}': {
      get: {
        tags: ['Donations'],
        summary: 'Get full donation detail',
        description:
          'The donation with donor/volunteer info attached, plus its full status history. Accessible ' +
          'to the donor who owns it, the assigned volunteer, or an admin — everyone else gets 403.',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        responses: {
          200: successEnvelope({
            type: 'object',
            properties: {
              donation: { $ref: '#/components/schemas/DonationDetail' },
              history: { type: 'array', items: { $ref: '#/components/schemas/DonationStatusHistoryEntry' } },
            },
          }),
          401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 422: commonErrors[422],
        },
      },
      patch: {
        tags: ['Donations'],
        summary: 'Update a donation request (owner only, pending only)',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        requestBody: {
          content: {
            'application/json': {
              schema: {
                type: 'object',
                properties: {
                  category: { type: 'string', enum: DONATION_CATEGORY_VALUES },
                  quantity: { type: 'integer', minimum: 1 },
                  description: { type: 'string', maxLength: 500 },
                  photo: { type: 'string', maxLength: 255 },
                  pickupLocation: { type: 'string', maxLength: 255 },
                  pickupTime: { type: 'string', format: 'date-time' },
                },
              },
            },
          },
        },
        responses: { 200: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409], 422: commonErrors[422] },
      },
      delete: {
        tags: ['Donations'],
        summary: 'Cancel (soft-delete) a donation request (owner only, pending only)',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        responses: { 200: successEnvelope(null, 'Cancelled.'), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409] },
      },
    },
    '/donations/{id}/accept': {
      patch: {
        tags: ['Donations'],
        summary: 'Accept a pending donation (volunteer only)',
        description: 'Transaction + row-lock safe; if another volunteer already accepted it, returns 409.',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        responses: { 200: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409] },
      },
    },
    '/donations/{id}/schedule': {
      patch: {
        tags: ['Donations'],
        summary: 'Schedule a pickup time (assigned volunteer only)',
        description: 'Only allowed when status is "accepted".',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        requestBody: {
          required: true,
          content: { 'application/json': { schema: { type: 'object', required: ['scheduledAt'], properties: { scheduledAt: { type: 'string', format: 'date-time' } } } } },
        },
        responses: { 200: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409], 422: commonErrors[422] },
      },
    },
    '/donations/{id}/on-the-way': {
      patch: {
        tags: ['Donations'],
        summary: 'Mark as "on the way" to pickup (assigned volunteer only)',
        description: 'Only allowed when status is "scheduled".',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        responses: { 200: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409] },
      },
    },
    '/donations/{id}/picked-up': {
      patch: {
        tags: ['Donations'],
        summary: 'Mark as "picked up" (assigned volunteer only)',
        description: 'Only allowed when status is "on_the_way".',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        responses: { 200: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409] },
      },
    },
    '/donations/{id}/complete': {
      patch: {
        tags: ['Donations'],
        summary: 'Mark as "completed" (assigned volunteer only)',
        description: 'Only allowed when status is "picked_up".',
        security: bearerSecurity,
        parameters: [idPathParam('id', 'Donation ID')],
        responses: { 200: successEnvelope({ type: 'object', properties: { donation: { $ref: '#/components/schemas/Donation' } } }), 401: commonErrors[401], 403: commonErrors[403], 404: commonErrors[404], 409: commonErrors[409] },
      },
    },
  };
}

